import{_ as n}from"./chunks/icon.B7gRmRZx.js";import{_ as t,a as i}from"./chunks/block-menu.Dr9I8l8O.js";import{_ as r,o as s,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"Logic Studio","description":"Erste öffentliche Testversion des grafischen Funktionsplan-Editors für Home Assistant.","frontmatter":{"title":"Logic Studio","description":"Erste öffentliche Testversion des grafischen Funktionsplan-Editors für Home Assistant."},"headers":[],"relativePath":"projects/logic-studio/index.md","filePath":"projects/logic-studio/index.md","lastUpdated":1794146905000}'),l={name:"projects/logic-studio/index.md"};function d(u,e,g,c,p,h){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="logic-studio" tabindex="-1"><img class="package-icon" src="'+n+'" width="40" height="40" alt=""> Logic Studio <a class="header-anchor" href="#logic-studio" aria-label="Permalink to &quot;&lt;img class=&quot;package-icon&quot; src=&quot;/images/logic-studio/icon.svg&quot; width=&quot;40&quot; height=&quot;40&quot; alt=&quot;&quot;&gt; Logic Studio&quot;">​</a></h1><p><strong>0.1.6 – erste öffentliche Testversion, 8. November 2026.</strong> Logic Studio ist eine eigene HA-App für grafische Funktionspläne. Sie ist unabhängig von Grafik Visual Studio und Blocks for HA. Die Oberfläche ist derzeit <strong>Deutsch</strong>; diese Anleitung gibt es in <strong>DE/EN/FR</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Testversion</p><p>Zuerst auf einem Testsystem installieren und vorher ein vollständiges Backup erstellen. Native Detailoptionen werden zunächst als JSON bearbeitet. Die App schreibt keine Automationen oder Skripte in HA zurück und schaltet keine Geräte. Erzeugte Ausgaben immer prüfen und selbst in HA installieren.</p></div><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/logic-studio-v0.1.6" target="_blank" rel="noreferrer">GitHub-Testrelease und ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/logic_studio" target="_blank" rel="noreferrer">Quellcode im Sammel-Repository</a></p><h2 id="testinstallation-aus-github" tabindex="-1">Testinstallation aus GitHub <a class="header-anchor" href="#testinstallation-aus-github" aria-label="Permalink to &quot;Testinstallation aus GitHub&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/supervisor_add_addon_repository/?repository_url=https%3A%2F%2Fgithub.com%2Frockbaer2007%2Fugso-ha-mqtt-addons" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/supervisor_add_addon_repository.svg" alt="Repository in Home Assistant hinzufügen"></a></p><ol><li>In <strong>Einstellungen → Apps → App-Store → Repositorys</strong> die folgende Adresse eintragen. Ist „UGSo HA Apps“ schon eingerichtet, nur nach Updates suchen.</li><li><strong>UGSo Logic Studio</strong> auswählen und installieren. Falls experimentelle Apps ausgeblendet sind, im HA-Profil den erweiterten Modus aktivieren.</li><li>Starten und die Benutzeroberfläche öffnen. Unterstützt werden <strong>HA OS/Supervised</strong>, <strong>amd64 und aarch64</strong>. Der erste Container-Build kann einige Minuten dauern. Dies ist kein HACS-/Marketplace-Frontend-Paket.</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Vorhandene lokale Testinstallation erhalten:</strong> GitHub- und lokale App haben verschiedene Repository-IDs und getrennte Daten. Den alten Plan über <strong>Projekt</strong> als JSON exportieren und in der GitHub-App über <strong>Öffnen</strong> importieren. Es gibt keine automatische Migration oder Deinstallation. Projekt und Paletteinstellungen der jeweiligen App bleiben unter <code>/data</code> gespeichert.</p><h2 id="zwei-arten-von-planen" tabindex="-1">Zwei Arten von Plänen <a class="header-anchor" href="#zwei-arten-von-planen" aria-label="Permalink to &quot;Zwei Arten von Plänen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plan</th><th>Zweck und Ausgabe</th></tr></thead><tbody><tr><td>Wertplan</td><td>Typisierte Ein-/Ausgänge, Logik, Mathematik, Auswahl sowie Speicher, Flanken, Timer und Zähler. 33 implementierte Typen; weitere Referenztypen sind als Vorlagen gekennzeichnet. Ausgabe als HA-Automation, HA-Skript oder JavaScript-Funktion mit Host-Schnittstelle.</td></tr><tr><td>Nativer HA-Ablauf</td><td>Automationen, Skripte und Blueprints importieren und als verschachtelte Bausteine bearbeiten. 53 zusätzliche HA-Typen für Auslöser, Bedingungen, Zweige, Schleifen, Warteaktionen, Variablen und Blueprint-Eingaben. Ausgabe ausschließlich als native HA-YAML.</td></tr></tbody></table><p>Wertpläne können mit Demo-/Momentaufnahmewerten simuliert werden. Persistente Wertbausteine benötigen die dokumentierten HA-Texthelfer bzw. einen JavaScript-Speicher-Host. Native HA-Abläufe werden im Editor weder ausgeführt noch automatisch in JavaScript umgerechnet. Die JavaScript-Ausgabe ist kein ioBroker-Skript.</p><h2 id="import-und-bearbeitung" tabindex="-1">Import und Bearbeitung <a class="header-anchor" href="#import-und-bearbeitung" aria-label="Permalink to &quot;Import und Bearbeitung&quot;">​</a></h2><p><strong>HA importieren</strong> öffnen, Automationen/Skripte/Blueprints auswählen und <strong>Aus HA einlesen</strong>, eine YAML-/JSON-Datei oder eingefügten Text verwenden. Eintrag und Vorschau prüfen, dann <strong>Import übernehmen</strong>. Vorher den eigenen Plan als JSON sichern; zusätzlich entstehen Projekt- und Quelldateisicherungen.</p><p>Der HA-Konfigurationsordner ist <strong>schreibgeschützt</strong> eingebunden. Gelesen werden <code>automations.yaml</code>, <code>scripts.yaml</code> und Blueprint-Dateien. Vor dem Parsen kopiert die App Quellen unter <code>/data/ha-source-backups/&lt;Zeitstempel&gt;/</code> mit ursprünglichem Namen. <code>secrets.yaml</code> wird nicht geöffnet; <code>!secret</code> und <code>!include</code> bleiben unaufgelöst. Bei ausgelagerten Include-Dateien die tatsächliche Datei selbst importieren.</p><p>Orange <strong>FLOW</strong>-Leitungen bilden Reihenfolge und Zweige ab: Zweigausgang → <strong>DO</strong>, anschließend <strong>NEXT → DO</strong>. Gelbe <strong>VALUE/REF</strong>-Leitungen zeigen Blueprint-Parameter und deren <code>!input</code>-Verwendung. Eigenschaften enthalten HA-Konfiguration und Zweigpfade als JSON. Parameter-/Feldschlüssel müssen eindeutig sein. Unbekannte Abschnitte bleiben als <strong>YAML_ORIGINAL</strong> erhalten; fehlende Verbindungen können den Export sperren.</p><p><img src="'+t+'" alt="Importvorschau vorhandener HA-Blueprints"></p><p>Das <strong>⋮-Menü</strong> jedes Bausteins bietet <strong>Eigenschaften, Duplizieren und Löschen</strong>. Duplizieren übernimmt Eigenschaften ohne Leitungen. Löschen entfernt zugehörige Leitungen; <strong>Rückgängig</strong> stellt sie wieder her. Suche, Favoriten und zuletzt benutzte Bausteine erleichtern die Auswahl.</p><p><img src="'+i+'" alt="Drei-Punkte-Menü im Funktionsplan"></p><h2 id="prufstand-und-grenzen" tabindex="-1">Prüfstand und Grenzen <a class="header-anchor" href="#prufstand-und-grenzen" aria-label="Permalink to &quot;Prüfstand und Grenzen&quot;">​</a></h2><p>Der Funktionsstand <strong>0.1.5</strong> wurde auf <strong>.193 / HA Core 2026.10.4</strong> geprüft: echter Blueprint-Import, Automation-/Skript-/Blueprint-Beispiele, inhaltlich gleiche YAML-Ausgabe und Menüaktionen. <strong>0.1.6</strong> ist dessen erste öffentliche Paketierung. 22 Node- und acht Python-Tests prüfen unter anderem Export, Persistenz, verschachtelte Abläufe und sicheren Quelldateiimport; die GitHub-Prüfung baut zusätzlich den Container.</p><p>Keine vollständige HA-Semantikprüfung im Editor: Ziele, Templates und Selektoren in HA kontrollieren. Kommentare, YAML-Anker und Formatierung werden nicht originalgetreu rekonstruiert. Importgrenzen: <strong>1 MB, 200 Bausteine, 500 Leitungen</strong>, begrenzte Verschachtelung und bis zu 250 Blueprint-Dateien in üblichen Ordnern. Regler, Kalender und eigene Unterpläne sind teilweise noch Vorlagen.</p><p>Für lokale Tests das Release-ZIP vollständig entpacken, Python 3.10+ und die Pakete aus <code>requirements.txt</code> installieren; unter Windows danach <strong>Start-Demo.cmd</strong> starten. <code>http://127.0.0.1:4180/</code> zeigt Demo-Entitäten ohne HA-Verbindung. Das ZIP enthält außerdem <code>addon/logic_studio/</code> für lokale App-Installationen.</p><p>Fehler bitte mit Versionen, Architektur und einem kleinen anonymisierten Beispiel <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">auf GitHub melden</a>. Keine Zugangsdaten, persönlichen Automationen oder Vollbackups veröffentlichen. Weitere Anleitungen und Prüfbericht liegen im Paket. Lizenz: MIT; Herkunft der übernommenen Block-Metadaten siehe <code>THIRD-PARTY.txt</code>.</p>',24)])])}const A=r(l,[["render",d]]);export{k as __pageData,A as default};
